#!/usr/bin/env python3
"""Human-readable report generated from actual saved metrics only."""
import argparse,csv,json,pathlib
BASE=pathlib.Path(__file__).resolve().parents[1]
def main():
 ap=argparse.ArgumentParser();ap.add_argument('runs',nargs='+',type=pathlib.Path);a=ap.parse_args();rows=list(csv.DictReader((a.runs[0]/'behavioral_results.csv').open()));summary=json.loads((a.runs[0]/'summary.json').read_text());comp=list(csv.DictReader((BASE/'comparison/comparison.csv').open()));repro=json.loads((BASE/'comparison/reproducibility.json').read_text());validation=json.loads((BASE/'validation.json').read_text())
 lines=['# RE01–RE03: поведенческие результаты из сохранённых outputs','',f"Исходных контрактов: {repro['source_contracts']}; существующих вариантов исходников: {repro['variant_sources']}; полных чистых запусков: {repro['clean_process_launches']}; повторов на контракт: {repro['repetitions_per_contract']}; сценарных испытаний: {validation['scenario_trials']}; шагов снятия: {validation['withdrawal_steps']}.",'','Два повтора — проверка воспроизводимости, а не независимые контракты. Исходники CEI/Mutex/комбинации не изменялись. UC01–UC03 закрыты как exploratory behavioral pilot и не перезапускались.','', '| Контракт | Сравнение | Результат | Обычная и разрешённая функциональность |','|---|---|---|---|']
 labels={'equal observed protection':'равная наблюдаемая защита','additional observed protection':'дополнительная наблюдаемая защита','worse/security regression':'ухудшение защиты','functional regression':'функциональная регрессия','trade-off':'компромисс','insufficient evidence':'недостаточно данных'}
 for r in comp:lines.append(f"| {r['contract_id']} | {r['comparison']} | {labels[r['classification']]} | {r['ordinary_and_permitted_functionality_preserved']} |")
 lines+=['','| Контракт | Вариант | Выплата при одном повторном входе, wei | Избыточная выплата E, wei | Несоответствие кредита M, wei | Непокрытые записанные требования D, wei | Нарушения безопасности |','|---|---|---:|---:|---:|---:|---|']
 for r in rows:
  if r['scenario']=='S1':lines.append('| '+' | '.join([r['contract_id'],r['variant'],r['payout_wei'],r['excess_payout_wei'],r['credit_mismatch_wei'],r['claim_shortfall_wei'],r['security_violated_ids']])+' |')
 lines+=['','Таблица показывает первый запуск; совпадение всех сравниваемых поведенческих полей при повторе: '+json.dumps(repro['behavioral_metrics_identical'])+'.','', '| Контракт | Вариант | Обычные разрешённые снятия за повтор | Откат отказа | Свойства безопасности S1 |','|---|---|---|---|---|']
 for cid,variants in summary.items():
  for v,s in variants.items():lines.append(f"| {cid} | {v} | {s['ordinary_allowed_operations_passed']}/{s['ordinary_allowed_operations_expected']} | {s['rejection_rollback_passed']} | {s['security_scenarios_satisfied']}/{s['security_scenarios_completed']} |")
 lines+=['','I1: превышение разрешённой выплаты; I2: несогласованность выплаты и учёта; I3: сохранение финансового потока; I5: покрытие оставшихся записанных требований активами. I4 проверяет откат, I6 — разрешённые операции. Эти проверки не являются независимыми уязвимостями и не складываются в защитную оценку.','', 'В RE01 baseline повторное вычитание вызывает uint256-wrap кредитной записи. Огромные M/D отражают фактическую порчу машинного состояния, а не правдоподобную денежную стоимость; отдельно сохраняются сырое значение кредита и измеренная избыточная выплата. В RE02 aggregate может совпадать с фактическим ETH, но не с суммой оставшихся credit; обе величины записаны отдельно. В RE02/RE03 успешный вложенный вызов под CEI не даёт дополнительной выплаты и не считается слабее блокировки вызова Mutex, когда свойства совпадают.','',f"Проверка доказательств: {validation['status']}; прежних файлов без изменений: {validation['previous_files_preserved']}; фактических трасс сверено: {validation['actual_traces_crosschecked']}; статических запусков: {validation['static_tool_runs']}; новых PES: {validation['PES_values']}.",'', 'Ограничения: один заранее известный ограниченный повторный вход, три источника, фиксированные суммы и бюджет газа, один локальный получатель, известные предыдущие результаты, чтение закрытого storage по явной схеме. Нет доказательства полной функциональной эквивалентности, защиты от всех видов reentrancy или реальной вероятности предотвращения атак. Другие функции, cross-function reentry, глубины/газовые границы, живые сети не тестировались.']
 (BASE/'generated_results.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
